import React, { useEffect, useState } from "react";
import {
  Box,
  Grid,
  Typography,
  Avatar,
  useTheme,
  useMediaQuery,
  Card,
  CardContent,
  Rating,
  CircularProgress,
  Button,
  Container,
} from "@mui/material";
import { motion } from "framer-motion";
import FormatQuoteIcon from '@mui/icons-material/FormatQuote';
import { Link as RouterLink } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { getAllTestimonials } from "../redux/slices/testimonialSlice";

// --- Animation variants for Framer Motion ---
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.5,
    },
  },
};

const TestimonialSectionHome = () => {
  const dispatch = useDispatch();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const { testimonials, loading, error } = useSelector((state) => state.testimonials);
  const [hasData, setHasData] = useState(false);

  useEffect(() => {
    // Fetch testimonials from API
    dispatch(getAllTestimonials());
  }, [dispatch]);

  useEffect(() => {
    // Check if testimonials array has data
    if (testimonials && testimonials.length > 0) {
      setHasData(true);
    } else {
      setHasData(false);
    }
  }, [testimonials]);

  // Show only the first 4 testimonials on the home page
  const visibleTestimonials = testimonials.slice(0, 4);

  // If loading, show loading spinner
  if (loading) {
    return (
      <Box sx={{ background: "#f9fafb", width: "100%", py: 6 }}>
        <Container maxWidth="xl">
          <Box textAlign="center" sx={{ py: 6 }}>
            <CircularProgress />
            <Typography sx={{ mt: 2 }}>Loading Testimonials...</Typography>
          </Box>
        </Container>
      </Box>
    );
  }

  // If no testimonials data, don't show the section at all
  if (!loading && !hasData) {
    return null; // This will hide the entire section
  }

  return (
    <Box
      sx={{
        background: "#f9fafb",
        width: "100%",
      }}
    >
      <Container maxWidth="xl" sx={{
        display: "flex",
        flexDirection: "column",
        gap: "50px",
        px: { xs: 3, sm: 6, md: 10, lg: 16 },
        py: { xs: 3, sm: 6, md: 8, lg: 10 },
      }}>
        {/* Section Title */}
        <Box textAlign="center">
          <Typography
            variant="h3"
            component="h2"
            sx={{
              fontWeight: 800,
              fontSize: { xs: "2rem", sm: "2.5rem", md: "2.8rem" },
              color: "#101828",
              lineHeight: 1.3,
              mb: "10px",
            }}
          >
            What Our <Box component="span" sx={{ color: '#2E9E53' }}>Clients Say</Box>
          </Typography>
          <Typography
            variant="body1"
            sx={{
              color: "#8b8e94",
              fontWeight: 400,
              fontSize: { xs: "1rem", md: "1.1rem" },
              maxWidth: 650,
              mx: "auto",
            }}
          >
            Discover how businesses like yours have achieved success and growth by partnering with BizBridge. Real stories, real results.
          </Typography>
        </Box>

        {hasData && (
          <>
            <motion.div
              variants={containerVariants}
              initial="hidden"
              animate="visible"
            >
              <Grid
                container
                spacing={isMobile ? 3 : 4}
                justifyContent="center"
                alignItems="stretch"
              >
                {visibleTestimonials.map((testimonial, index) => (
                  <Grid item xs={12} sm={6} md={3} key={testimonial._id || index}>
                    <motion.div variants={itemVariants} style={{ height: '100%' }}>
                      <Card
                        sx={{
                          height: "100%",
                          borderRadius: "12px",
                          boxShadow: "none",
                          border: "1px solid #e5e7eb",
                          display: 'flex',
                          flexDirection: 'column',
                        }}
                      >
                        <CardContent sx={{ textAlign: "left", p: 3, flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                          {/* Rating - using default 5 stars as rating field doesn't exist in your API */}
                          {/* <Rating 
                            value={5} 
                            readOnly 
                            precision={0.5} 
                            size="small" 
                            sx={{ marginBottom: "20px" }} 
                          /> */}
                          <Typography
                            variant="body2"
                            color="##494949"
                            sx={{ marginBottom: "20px", flexGrow: 1 }}
                          >
                            {testimonial.description || "Great service and quality!"}
                          </Typography>

                          <Box sx={{ mt: 'auto' }}>
                            <Box sx={{ display: "flex", alignItems: "center", gap: "12px" }}>
                              <Avatar
                                src={testimonial.image}
                                alt={testimonial.name}
                                sx={{ width: 42, height: 42 }}
                              >
                                {testimonial.name?.charAt(0) || "C"}
                              </Avatar>
                              <Box sx={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 0 }}>
                                <Typography variant="subtitle2" fontWeight={600}>
                                  {testimonial.name || "Customer"}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                  {testimonial.designation} at {testimonial.companyName}
                                </Typography>
                              </Box>
                            </Box>
                          </Box>
                        </CardContent>
                      </Card>
                    </motion.div>
                  </Grid>
                ))}
              </Grid>
            </motion.div>
            <Box textAlign="center">
              <Button
                component={RouterLink}
                to="/testimonials"
                variant="contained"
                sx={{
                  borderRadius: "50px",
                  px: 5,
                  py: 1.5,
                  fontWeight: 600,
                  bgcolor: "#0B4064",
                  color: "#fff",
                  textTransform: "none",
                  fontSize: "1rem",
                  boxShadow: "none",
                }}
              >
                View All Testimonials
              </Button>
            </Box>
          </>
        )}
      </Container>
    </Box>
  );
};

export default TestimonialSectionHome;