// Helper function to get initials
const getInitials = (name) => {
  if (!name) return "BU";
  return name
    .split(" ")
    .map((word) => word[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);
};

export const { setTabValue, setSearchValue, addNewConnection, clearError } =
  buyerNetworkSlice.actions;
export default buyerNetworkSlice.reducer;
