import React, { useEffect, useState } from "react";
import QRCode from "react-qr-code";
import axios from "../axiosInstance";

const GenerateSellerQR = ({ sellerId }) => {
  const [qrValue, setQrValue] = useState("");
  const [loading, setLoading] = useState(true);
  
  useEffect(() => {
    fetchKioskCategory();
  }, []);

  const fetchKioskCategory = async () => {
    try {
      const res = await axios.get("/api/v1/buyer-categories?page=1?limit=10");

      const kiosk = res.data.data.find((cat) => cat.name === "Kiosk");

      if (!kiosk) {
        alert("Kiosk buyer category not found");
        return;
      }

      const qrUrl = `${window.location.origin}/scan?sellerId=${sellerId}&buyerCategoryId=${kiosk._id}`;

      setQrValue(qrUrl);

      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  if (loading) return <p>Generating QR...</p>;

  return (
    <div style={{ textAlign: "center" }}>
      <h2>Seller QR Code</h2>

      <div
        style={{
          background: "white",
          padding: "16px",
          display: "inline-block",
        }}
      >
        <QRCode value={qrValue} size={220} />
      </div>

      <p style={{ marginTop: "12px" }}>
        Buyer scan kare aur direct products dekhe
      </p>
    </div>
  );
};

export default GenerateSellerQR;
