import { useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import axios from "../axiosInstance";

const QRScan = () => {
  const navigate = useNavigate();
  const [params] = useSearchParams();

  const sellerId = params.get("sellerId");
  const buyerCategoryId = params.get("buyerCategoryId");


  useEffect(() => {
    const token = localStorage.getItem("token");

    // 1️⃣ User login nahi hai
    if (!token) {
      navigate("/register");
      return;
    }

    // 2️⃣ User login hai → connection banao
    createConnection(token);
  }, []);


  useEffect(() => {
  console.log("SCAN PAGE LOADED");
  console.log("sellerId:", sellerId);
  console.log("buyerCategoryId:", buyerCategoryId);
}, []);


  const createConnection = async (token) => {
    try {
      // Logged in user ka data backend se
      const userRes = await axios.get("/api/v1/auth/profile", {
        headers: { Authorization: `Bearer ${token}` },
      });

      const user = userRes.data.user;

      // 3️⃣ Buyer-Seller connection create
      const connectionRes = await axios.post(
        "/api/v1/buyer-seller-connections/connection",
        {
          buyerCategory: buyerCategoryId,
          buyerEmail: user.email || null,
          buyerPhone: user.phone || null,
          seller: sellerId,
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      const connectionId = connectionRes.data.connection._id;

      // 4️⃣ Auto ACCEPT
      await axios.put(
        `/api/v1/buyer-seller-connections/connection/${connectionId}/status`,
        { status: "Accepted" },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      // 5️⃣ Products page par navigate
      navigate("/buyer-dashboard/view-products", {
        state: {
          connectionId,
          otherUserId: sellerId,
        },
      });
    } catch (error) {
      console.error(error);
    }
  };

  return <p>QR scan processing...</p>;
};

export default QRScan;
